<template>
  <ForgeDialog title="PHP extensions" description="Browse the extension catalog, install a compatible release, or disable a configured extension." eyebrow="RUNTIME / PHP" wide @close="emit('close')">
    <div class="ext-panel"><div class="ext-toolbar"><input v-model="query" placeholder="Search extensions" @keyup.enter="search" /><button class="action-button" :disabled="entry.fetching || entry.installing" @click="search">{{ entry.fetching ? 'Loading…' : 'Search' }}</button><button class="action-button" :disabled="entry.fetching || entry.installing" @click="refresh">Refresh</button></div><div v-if="entry.error" class="forge-alert forge-alert--error">{{ entry.error }}</div><div v-if="entry.partial" class="forge-alert">Catalog is partial; refresh to retry unavailable providers.</div><div class="ext-profile" v-if="entry.profile"><b>PHP {{ entry.profile.version }}</b><span>{{ entry.profile.architecture }} · {{ entry.profile.build }}</span><small>{{ entry.profile.ini }}</small></div><div class="ext-list"><article v-for="row in rows" :key="row.key" class="ext-row"><div><b>{{ row.name }}</b><small>{{ row.description || 'No description available.' }}</small><em>{{ row.status === 'loaded' ? 'Loaded' : row.status === 'unloaded' ? 'Configured, not loaded' : 'Available' }}</em></div><div class="ext-actions"><button v-if="row.packageName && row.status !== 'loaded'" class="primary-button" :disabled="entry.installing || entry.fetching" @click="install(row.packageName)">{{ entry.installing && entry.operation?.name === row.name ? 'Installing…' : row.status === 'unloaded' ? 'Repair' : 'Install' }}</button><button v-if="row.configuredName" class="action-button" :disabled="entry.installing || entry.fetching" @click="disable(row.configuredName)">Disable</button></div></article><p v-if="!rows.length&&!entry.fetching" class="empty-copy">No extensions match this search.</p></div><pre v-if="entry.log" class="ext-log">{{ entry.log }}</pre></div>
    <template #footer><span class="website-help">PHP will need to be restarted before a newly configured extension is loaded.</span></template>
  </ForgeDialog>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import windowsExtensions from '@/components/PHP/Extension/Windows/controller'
import { extensionRows } from '@/components/PHP/Extension/Windows/Catalog'
import type { SoftInstalled } from '@shared/app'
const props=defineProps<{version:SoftInstalled}>(); const emit=defineEmits<{close:[]}>(); const query=ref(''); const entry=computed(()=>windowsExtensions.entry(props.version)); const rows=computed(()=>extensionRows(entry.value.profile,entry.value.packages,query.value)); const search=()=>windowsExtensions.search(props.version,query.value); const refresh=()=>windowsExtensions.search(props.version,query.value,true); const install=(name:string)=>void windowsExtensions.install(props.version,name); const disable=(name:string)=>void windowsExtensions.disable(props.version,name); onMounted(()=>windowsExtensions.load(props.version))
</script>
<style scoped>
.ext-panel{display:grid;gap:12px;font-size:12px}.ext-toolbar{display:flex;gap:8px}.ext-toolbar input{flex:1;padding:9px 10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.ext-profile{display:grid;gap:4px;padding:10px;border:1px solid var(--pqt-border);border-radius:7px}.ext-profile span,.ext-profile small,.ext-row small{color:var(--pqt-text-muted)}.ext-profile small{font:10px var(--pqt-font-mono);word-break:break-all}.ext-list{display:grid;gap:6px;max-height:370px;overflow:auto}.ext-row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px 12px;border:1px solid var(--pqt-border);border-radius:7px}.ext-row>div:first-child{display:grid;gap:4px;min-width:0}.ext-row small{line-height:1.35}.ext-row em{font-size:9px;color:var(--pqt-accent);font-style:normal;text-transform:uppercase;letter-spacing:.08em}.ext-actions{display:flex;gap:6px;flex:none}.ext-log{max-height:110px;overflow:auto;padding:10px;border:1px solid var(--pqt-border);border-radius:7px;color:var(--pqt-text-muted);font:10px/1.5 var(--pqt-font-mono);white-space:pre-wrap}
</style>
